#!/usr/bin/env bash
#
# morning.sh — 60-second start-of-session orientation.
#
# What it does:
#   1. Fetch latest refs from all remotes
#   2. Show your local state (branch + dirty files)
#   3. Show your open PRs and their review status (gh required)
#   4. Show local branches that have unmerged commits
#   5. Print the Claude Code auto-memory index for this repo (if exists)
#   6. Print today's bucket from the active week plan in memory (if exists)
#
# Run BEFORE you start coding. Saves you the "what was I doing?" 20 minutes.
#
# Generated by the `dev-workflow` skill.
#
set -euo pipefail

# ── Auto-derive paths (portable across machines + worktrees) ──────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(dirname "$SCRIPT_DIR")"
# Auto-memory convention: ~/.claude/projects/-<dashed-encoded-repo-path>/memory/
MEMORY_DIR="$HOME/.claude/projects/-$(echo "$REPO_ROOT" | sed 's|/|-|g; s|^-||')/memory"

# ── Pretty output ──────────────────────────────────────────────────────────
log()   { printf '\033[0;34m→\033[0m %s\n' "$1"; }
ok()    { printf '  \033[0;32m✓\033[0m %s\n' "$1"; }
warn()  { printf '  \033[1;33m!\033[0m %s\n' "$1"; }
note()  { printf '  %s\n' "$1"; }

cd "$REPO_ROOT"

log "Today: $(date '+%A %Y-%m-%d')"
echo

# ── 1. Fetch ───────────────────────────────────────────────────────────────
log "Fetching all refs"
git fetch --all --prune --quiet 2>/dev/null && ok "fetched" || warn "fetch failed (offline or no remotes?)"
echo

# ── 2. Local state ─────────────────────────────────────────────────────────
log "Where you are"
note "branch: $(git branch --show-current)"
DIRTY=$(git status -s | wc -l | tr -d ' ')
if [[ "$DIRTY" == "0" ]]; then
  note "working tree clean"
else
  note "uncommitted changes:"
  git status -s | head -10 | sed 's/^/    /'
fi
echo

# ── 3. Open PRs (gh CLI) ───────────────────────────────────────────────────
log "Your open PRs"
if command -v gh >/dev/null 2>&1; then
  if command -v jq >/dev/null 2>&1; then
    gh pr list --author=@me --state=open --json number,title,headRefName,reviewDecision,baseRefName 2>/dev/null \
      | jq -r '.[] | "  #\(.number) [\(.headRefName) → \(.baseRefName)] \(.title)\n    review: \(.reviewDecision // "PENDING REVIEW")"' \
      || warn "gh CLI failed (auth issue?)"
  else
    gh pr list --author=@me --state=open 2>/dev/null | sed 's/^/  /' || warn "gh CLI failed"
  fi
else
  warn "gh CLI not installed — skip PR check (install: brew install gh)"
fi
echo

# ── 4. Branches ahead of main ──────────────────────────────────────────────
log "Local branches with unmerged commits"
# Detect main branch name (some repos use 'master', 'develop', etc.)
DEFAULT_BRANCH=$(git symbolic-ref refs/remotes/origin/HEAD 2>/dev/null | sed 's@^refs/remotes/origin/@@' || echo "main")
FOUND_ANY=0
while IFS= read -r branch; do
  AHEAD=$(git rev-list --count "$branch" "^$DEFAULT_BRANCH" 2>/dev/null || echo 0)
  if [[ "$AHEAD" != "0" ]]; then
    note "$branch: $AHEAD commits ahead of $DEFAULT_BRANCH"
    FOUND_ANY=1
  fi
done < <(git branch --format='%(refname:short)' | grep -vE "^($DEFAULT_BRANCH|HEAD)$")
[[ "$FOUND_ANY" == "0" ]] && note "(none — all local branches caught up)"
echo

# ── 5. Memory index ────────────────────────────────────────────────────────
log "Memory index"
if [[ -f "$MEMORY_DIR/MEMORY.md" ]]; then
  cat "$MEMORY_DIR/MEMORY.md" | sed 's/^/  /'
else
  warn "no MEMORY.md at $MEMORY_DIR — auto-memory not yet initialized for this repo"
fi
echo

# ── 6. Today's bucket from active week plan ────────────────────────────────
log "Today's bucket"
PLAN_FILE=$(grep -l "Week plan" "$MEMORY_DIR"/*.md 2>/dev/null | head -1)
if [[ -n "$PLAN_FILE" ]]; then
  DOW=$(date '+%a')  # Mon, Tue, Wed, Thu, Fri, Sat, Sun
  if [[ "$DOW" =~ ^(Mon|Tue|Wed|Thu|Fri)$ ]]; then
    # Extract the matching day's section: from "**Mon ..." to next "**Xxx ..."
    awk -v day="**$DOW " '
      $0 ~ "^\\*\\*[A-Z][a-z][a-z] " { in_section = 0 }
      index($0, day) == 1 { in_section = 1 }
      in_section { print "  " $0 }
    ' "$PLAN_FILE"
  else
    note "(weekend — no scheduled bucket; use buffer time as you see fit)"
  fi
else
  note "(no week plan file in memory — ask Claude to plan a week if you want one)"
fi
echo

ok "oriented"
